import{_ as t,o as s,c as r,ah as n}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Importer des élèves","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/secretariat/import-eleves.md","filePath":"src/guide/secretariat/import-eleves.md"}'),i={name:"guide/secretariat/import-eleves.md"};function a(l,e,o,u,d,c){return s(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="importer-des-eleves" tabindex="-1">Importer des élèves <a class="header-anchor" href="#importer-des-eleves" aria-label="Permalink to &quot;Importer des élèves&quot;">​</a></h1><p>La page <strong>Importer des élèves</strong>, dans l&#39;espace <strong>Élèves et admissions</strong>, reprend une liste d&#39;élèves et de leurs parents depuis un fichier Excel, au lieu de les saisir un par un. Elle sert surtout à la reprise d&#39;un établissement ou à une grosse inscription de rentrée. Un lien y mène aussi depuis la page <strong>Élèves</strong>.</p><p>Elle est ouverte à l&#39;administration et au secrétariat. L&#39;administration remplit les classes de tous les sites ; le secrétariat, celles de <strong>son site</strong> (celui de sa fiche employé).</p><h2 id="les-etapes" tabindex="-1">Les étapes <a class="header-anchor" href="#les-etapes" aria-label="Permalink to &quot;Les étapes&quot;">​</a></h2><ol><li><strong>Téléchargez le fichier</strong> Excel. Son premier onglet est la liste à remplir ; le second donne les classes de l&#39;année en cours que vous pouvez utiliser, avec leurs places restantes, et les mots acceptés.</li><li><strong>Remplissez-le</strong>, une ligne par élève.</li><li><strong>Vérifiez le fichier</strong> : rien n&#39;est enregistré, la page liste les lignes à corriger, ou annonce ce que l&#39;import ferait (élèves créés, déjà présents, inscriptions, parents rattachés).</li><li><strong>Importez</strong>.</li></ol><h2 id="les-colonnes" tabindex="-1">Les colonnes <a class="header-anchor" href="#les-colonnes" aria-label="Permalink to &quot;Les colonnes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Colonne</th><th>À savoir</th></tr></thead><tbody><tr><td>Nom, Prénom</td><td>Obligatoires.</td></tr><tr><td>Sexe</td><td>Masculin ou Féminin. Facultatif.</td></tr><tr><td>Date de naissance</td><td><strong>Obligatoire</strong>, en jour/mois/année (25/03/2010). Elle distingue deux homonymes et permet de réimporter un fichier sans doublon.</td></tr><tr><td>Lieu de naissance</td><td>Facultatif.</td></tr><tr><td>Matricule</td><td>Seulement si l&#39;école utilise le matricule. Il doit être unique.</td></tr><tr><td>Site, Classe</td><td>Facultatifs. La classe est celle de l&#39;année en cours, écrite comme dans ERA. Le site n&#39;est utile que si deux sites ont une classe du même nom. Sans classe, l&#39;élève est créé sans inscription.</td></tr><tr><td>Parent 1 et Parent 2</td><td>Nom, lien (Père, Mère, Tuteur légal ou Autre), téléphone, e-mail. Un parent a besoin au moins d&#39;un nom.</td></tr></tbody></table><p>Les colonnes sont reconnues par leur <strong>titre</strong> : ne les renommez pas, mais vous pouvez les déplacer ou en ajouter d&#39;autres, qui sont ignorées.</p><h2 id="ce-que-fait-l-import" tabindex="-1">Ce que fait l&#39;import <a class="header-anchor" href="#ce-que-fait-l-import" aria-label="Permalink to &quot;Ce que fait l&#39;import&quot;">​</a></h2><ul><li><strong>Tout ou rien.</strong> Le fichier est vérifié en entier : une date illisible, une classe inconnue ou pleine, un doublon dans le fichier, un e-mail invalide… et rien n&#39;est importé. Chaque ligne à corriger est listée (les trente premières).</li><li><strong>Les élèves déjà dans ERA</strong> (même nom, même prénom, même date de naissance) ne sont ni modifiés ni recréés. Ils sont seulement inscrits dans la classe de leur ligne s&#39;ils n&#39;ont pas encore d&#39;inscription cette année. Leurs parents ne sont pas touchés.</li><li><strong>Une classe pleine est refusée</strong>, en comptant les élèves du fichier. Pour dépasser une capacité, inscrivez l&#39;élève à la main en indiquant le motif.</li><li><strong>Les parents</strong> sont retrouvés par leur adresse e-mail, ce qui rattache frères et sœurs au même compte. Le premier parent de la ligne est le contact principal.</li><li><strong>Sans e-mail</strong>, le parent reçoit une adresse provisoire, jamais utilisée pour écrire. Deux lignes ne partagent un parent sans e-mail que si son nom <strong>et</strong> son téléphone sont les mêmes ; sinon, chaque élève a son parent. Complétez les adresses ensuite depuis la page <a href="/era-guide/guide/secretariat/parents.html">Parents</a>.</li><li><strong>Aucun e-mail n&#39;est envoyé.</strong> Les invitations se font ensuite, depuis la page Parents.</li></ul>',10)])])}const g=t(i,[["render",a]]);export{m as __pageData,g as default};
